1. Ensure the download and extraction directories exist by creating them if they do not already.
2. Build the full local file path within the download directory using the provided filename.
3. Attempt to download the content from the given URL and write it to the local zip file path; on any request-related failure, return a status message containing "Error" and an empty list.
4. Try to open the downloaded file as a zip archive and extract all contents into the extraction directory.
5. If extraction fails due to file or zip errors, return a status message containing "Error" and an empty list.
6. On successful extraction, list all files within the extraction directory and return a success status message along with this list of filenames.

### code
```python
import requests
from pathlib import Path
import zipfile
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")
def task_func(url, filename):
    DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
    ZIP_DIR.mkdir(parents=True, exist_ok=True)
    zip_path = DOWNLOAD_DIR / filename
    try:
        response = requests.get(url, stream=True)
        response.raise_for_status()
        with open(zip_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except requests.RequestException as e:
        return (f"Error downloading file: {e}", [])
    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            zf.extractall(ZIP_DIR)
    except (FileNotFoundError, zipfile.BadZipFile, OSError) as e:
        return (f"Error extracting zip file: {e}", [])
    filenames = []
    for p in ZIP_DIR.rglob("*"):
        if p.is_file():
            filenames.append(str(p))
    return ("Download and extraction successful", filenames)
```

